tools.example:
// Acoustics_Module/Tutorials,_Pipe_Acoustics/acoustics_pipe_system uses acbm on the inlet
model.component("comp1").physics().create("acbm", "BoundaryModeAcoustics", "geom1");
model.component("comp1").physics("acbm").selection().set(new int[]{1});
model.study().create("std1");
model.study("std1").create("mode", "ModeAnalysis");
model.study("std1").feature("mode").set("modeFreq", "2000[Hz]");
model.study("std1").feature("mode").set("neigs", 6);
model.study("std1").run();
// evaluate acbm.kn or the in-plane/out-of-plane velocity variables acbm.vip_rms, acbm.vop_rms

// Application Library: Acoustics_Module/Underwater_Acoustics/submarine_asymptotic_scattering
model.component("comp1").physics().create("paas", "PressureAcousticsAsymptoticScattering", "geom1");
model.component("comp1").physics("paas").feature("bpf1").set("PressureFieldType", "SphericalWave");
model.component("comp1").physics("paas").feature("bpf1").set("PressureAmplitudeSpherical", "p_ref");
model.component("comp1").physics("paas").feature("bpf1").set("SourcePointSpherical", new String[]{"-d_source", "0", "0"});
model.component("comp1").physics("paas").feature("epam1").set("FluidModel", "OceanAttenuation");
model.study().create("std1");
model.study("std1").create("freq", "Frequency");
model.study("std1").feature("freq").set("plist", "5[kHz]");
// Results: Radiation Pattern of paas.efc1.Lp_pext (target strength)

model.component("comp1").physics().create("pakh", "PressureAcousticsKirchhoffHelmholtz", "geom1");
// Wall subnode of the Radiating Object: Type = Velocity, v = (solid.u_tX, solid.u_tY, solid.u_tZ)
// taken from a Solid Mechanics frequency-domain solution of an engine or ship hull
// Results > Radiation Pattern: pakh.efc1.Lp_pext

// outdoor propagation with humidity-dependent absorption
model.component("comp1").physics("acpr").feature("fpam1").set("FluidModel", "AtmosphereAttenuation");
// user-defined complex fluid, e.g. a fitted porous material
model.component("comp1").physics("acpr").feature("fpam1").set("FluidModel", "FrequencyLinearElastic");
model.component("comp1").physics("acpr").feature("fpam1").set("LinearElasticOption", "Krho");
model.component("comp1").physics("acpr").feature("fpam1").set("K_eff", "1.4e5*(1+0.05i)");

// used for vent and wax-guard holes in Acoustics_Module/Electroacoustic_Transducers/full_ear_hearing_aid
model.component("comp1").physics("acpr").create("nra1", "NarrowRegionAcousticsModel", 3);
model.component("comp1").physics("acpr").feature("nra1").selection().set(new int[]{4});
model.component("comp1").physics("acpr").feature("nra1").set("DuctType", "CircularDuct");
model.component("comp1").physics("acpr").feature("nra1").set("a", "0.4[mm]");

model.component("comp1").physics("acpr").create("ms1", "MonopoleSource", 3);
model.component("comp1").physics("acpr").feature("ms1").selection().set(new int[]{2});
// source property name taken from the settings window field Qm
model.component("comp1").physics("acpr").feature("ms1").set("Qm", "1e3*exp(-((x^2+y^2+z^2)/(5[mm])^2))");

model.component("comp1").physics("acpr").create("ds1", "DipoleSource", 3);
model.component("comp1").physics("acpr").feature("ds1").selection().set(new int[]{3});
// vertical distributed force, e.g. from a vibrating fan blade region
model.component("comp1").physics("acpr").feature("ds1").set("qd", new String[]{"0", "0", "F0/Vsrc"});

model.component("comp1").physics("acpr").create("afs1", "AeroacousticFlowSource", 3);
model.component("comp1").physics("acpr").feature("afs1").selection().named("source_region");
model.component("comp1").physics("acpr").feature("afs1").set("AcousticAnalogy", "Lighthill");
model.component("comp1").physics("acpr").feature("afs1").set("useWindowFunction", "1");
// Multiphysics > Aeroacoustic Flow Source Coupling; Study: Transient Mapping, then Time to Frequency FFT, then Frequency Domain

// used in composite_dome_tweeter_freq, loudspeaker_driver_3d, horn_shape_optimization
model.component("comp1").physics("acpr").create("pmb1", "PerfectlyMatchedBoundary", 2);
model.component("comp1").physics("acpr").feature("pmb1").selection().named("outer_sphere");
model.component("comp1").physics("acpr").feature("pmb1").set("directionType", "radial");
model.component("comp1").physics("acpr").feature("pmb1").set("r0", new String[]{"0", "0", "0"});

// Application Library: Acoustics_Module/Building_and_Room_Acoustics/diffuser_schroeder_2d
for (int j = 1; j <= 6; j++) {
  String tag = "dport" + j;
  model.component("comp1").physics("acpr").feature("pport1").create(tag, "DiffractionOrderPort", 1);
  model.component("comp1").physics("acpr").feature("pport1").feature(tag).set("m", (j % 2 == 1 ? 1 : -1) * ((j + 1) / 2));
}

// Application Library: Acoustics_Module/Electroacoustic_Transducers/lumped_receiver_04cc
model.component("comp1").physics("acpr").create("lport1", "LumpedPort", 2);
model.component("comp1").physics("acpr").feature("lport1").selection().set(new int[]{8});
model.component("comp1").physics("acpr").feature("lport1").set("ConnectionType", "Circuit");
model.component("comp1").physics().create("cir", "Circuit", "geom1");
// in the circuit, an External I vs. U node references the lumped port

// used in perforated_muffler, diffuser_schroeder_2d, open_pipe and lumped_loudspeaker_driver
model.component("comp1").physics("acpr").create("ishb1", "InteriorSoundHard", 1);
model.component("comp1").physics("acpr").feature("ishb1").selection().set(new int[]{9, 10, 11});

// Application Library: Acoustics_Module/Electroacoustic_Transducers/loudspeaker_driver_transient
model.component("comp1").physics("actd").create("efc1", "ExteriorFieldCalculation", 1);
model.study("std1").create("tffft", "TimeToFreqFFT");
model.study("std1").feature("tffft").set("fftmaxfreq", "5[kHz]");
// Results > Radiation Pattern: actd.efc1.Lp_pext

// 3D transient radiation: spherical PML shell around the air domain
model.component("comp1").coordSystem().create("pml1", "PML");
model.component("comp1").coordSystem("pml1").selection().named("pml_shell");
model.component("comp1").coordSystem("pml1").set("ScalingType", "Spherical");
model.component("comp1").coordSystem("pml1").set("stretchingType", "rational");

model.component("comp1").physics("pate").create("md1", "MaterialDiscontinuity", 1);
model.component("comp1").physics("pate").feature("md1").selection().named("water_tissue_interface");
// the default TotalFieldsContinuity node tfc1 needs no settings

// high-frequency engine noise: vibration from a Solid Mechanics study mapped onto the housing
model.component("comp1").physics("pakh").feature("ro1").selection().named("housing");
model.component("comp1").physics("pakh").feature("ro1").feature("wall1").set("v", new String[]{"solid.u_tX", "solid.u_tY", "solid.u_tZ"});
